import json
from typing import Tuple, Dict

# 模擬資料儲存空間
notes = []
next_id = 1


def handle(method: str, path: str, body: bytes) -> Tuple[int, Dict]:
    global notes, next_id

    if path == '/notes':
        if method == 'GET':
            return (200, notes)
        elif method == 'POST':
            data = json.loads(body.decode('utf-8'))
            new_note = {'id': next_id, 'text': data['text']}
            notes.append(new_note)
            next_id += 1
            return (201, new_note)
        else:
            return (405, {'error': 'Method Not Allowed'})
    elif path.startswith('/notes/'):
        note_id = int(path.split('/')[-1])
        if method == 'DELETE':
            for i, note in enumerate(notes):
                if note['id'] == note_id:
                    del notes[i]
                    return (200, {'message': 'Note deleted'})
            return (404, {'error': 'Note not found'})
        else:
            return (405, {'error': 'Method Not Allowed'})
    else:
        return (404, {'error': 'Not Found'})

